export function mergeContacts(existing: Contact[], incoming: Contact[]): Contact[] {
  const result = [...existing];
  // Maps normalized email -> position in `result`, so each lookup is O(1) instead of a scan.
  // The first entry with a given email wins, matching the previous findIndex behavior.
  const indexByEmail = new Map<string, number>();
  result.forEach((entry, position) => {
    const key = normalizeEmail(entry.email);
    if (!indexByEmail.has(key)) indexByEmail.set(key, position);
  });

  for (const contact of incoming) {
    const key = normalizeEmail(contact.email);
    const index = indexByEmail.get(key);
    if (index === undefined) {
      indexByEmail.set(key, result.length);
      result.push(contact);
    } else {
      result[index] = mergeContact(result[index], contact);
    }
  }
  return result;
}

